      "claim": "Imatinib, a heteroaryl amide with a basic piperazine, has absolute bioavailability ~98%, supporting high oral F for the query's amide/amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Tazemetostat, a morpholine-containing amide with high transfer, has absolute bioavailability ~33% (range 20–50%), still above the 20% threshold and consistent with high classification.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Sematilide, an amide with a basic amine, has absolute bioavailability ~46–59%, above the threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "LY3000328, an amide with morpholine/piperazine features, has oral bioavailability at least 48–66%, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small, moderately lipophilic morpholine-amide with favorable physicochemical properties. Multiple high-transfer analogues containing morpholine/piperazine and amide/chloroaryl motifs show absolute oral bioavailability well above 20%, ranging from ~33% to ~100%. Modified-release formulation may alter absorption kinetics but is unlikely to reduce total bioavailability below the 20% threshold given the consistent high-F evidence.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule itself.",
    "The effect of the modified-release formulation on total oral bioavailability is not directly evidenced.",
    "First-pass metabolism and transporter-mediated effects are not quantitatively characterized for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

